"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[5748],{3199(e){e.exports=JSON.parse('{"title":"RSC\uc758 \ubcf4\uc548, \ub09c \ub2e4\ub974\uac8c \ubcf8\ub2e4.","date":"2025-04-03","coverUrl":"/kudzu-based-bench/assets/notion/aa5228ae3e2554e7.png","html":"<h2 data-notion-block-id=\\"1c3e548d-8a8e-80fd-97e3-c81f618509ea\\" id=\\"1c3e548d-8a8e-80fd-97e3-c81f618509ea\\">RSC\uc758 \ubcf4\uc548, \ub09c \ub2e4\ub974\uac8c \ubcf8\ub2e4.</h2><a href=\\"https://nextjs.org/blog/security-nextjs-server-components-actions\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/security-nextjs-server-components-actions</a><p data-notion-block-id=\\"1c3e548d-8a8e-8034-9c60-c0b3f763e2c4\\">Next.js\uc5d0\uc11c <a href=\\"https://zhero-web-sec.github.io/research-and-things/nextjs-and-the-corrupt-middleware\\">middleware bypass \ucde8\uc57d\uc810</a>\uc774 \ubc1c\uc0dd\ud588\uc5c8\uc2b5\ub2c8\ub2e4. \ubb3c\ub860 \ud328\uce58\uac00 \uc774\ub8e8\uc5b4\uc84c\uc9c0\ub9cc, RSC\uc640 App router\uc5d0\uc11c\uc758 \ubcf4\uc548\uc774 \ub2e4\ub974\ub2e4\ub294 \uc810\uc774 \ub2e4\uc2dc \uc7ac\uc870\uba85\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ub610\ud55c \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub4ef\uc774, <a href=\\"https://ones-to-watch.ethansup.net/news/post/e118a44c-46de-44b7-9492-998633298d32#f29e4a24-df9a-40b1-adc6-3d1fd524a9a4\\">authorization\uc744 middleware\uc5d0 \ub123\ub294 \uac83\uc774 \uc88b\uc9c0 \uc54a\ub2e4\ub294 \uac83</a> \ub610\ud55c \ub2e4\uc2dc \uc0dd\uac01\ud574\ubcfc\ub9cc \ud569\ub2c8\ub2e4. App Router\uac00 \uc544\uc9c1\uae4c\uc9c0\ub294 \uc77c\ubd80\uac00 \ubd88\uc548\uc815\ud558\uae30\uc5d0 <a href=\\"https://eduardoboucas.com/posts/2025-03-25-you-should-know-this-before-choosing-nextjs/\\">\ub2e4\ub978 \uae30\uc220 \uc120\ud0dd \ub610\ud55c \uace0\ub824</a>\ud574\ubcfc\ub9cc \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1c9e548d-8a8e-800b-8cff-de429634e21b\\" id=\\"1c9e548d-8a8e-800b-8cff-de429634e21b\\">\ubc14\uc774 \ubc14\uc774, Turbofan.</h2><a href=\\"https://v8.dev/blog/leaving-the-sea-of-nodes\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://v8.dev/blog/leaving-the-sea-of-nodes</a><p data-notion-block-id=\\"1c9e548d-8a8e-80c5-8b46-d772e4225812\\">V8 \ucef4\ud30c\uc77c\ub7ec\uac00 \uc5b4\ub5bb\uac8c \ubc1c\uc804\ub418\uc5c8\ub294\uc9c0, \uadf8 \uc911\uc5d0\uc11c Sea of Nodes \uc544\ud0a4\ud14d\uccd0\ub97c \uc0ac\uc6a9\ud558\uc5ec \ub9cc\ub4e0 Turbofan\uc774 Control-Flow Graph \uae30\ubc18\uc778 TurboShaft\ub85c \ubc14\uafb8\uace0 \uc788\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. SoN(Sea of Nodes)\uacfc CFG(Control-Flow Graph)\ub97c \ubab0\ub77c\ub3c4 \uce5c\uc808\ud558\uac8c \uc124\uba85\ud574\uc8fc\uae30\uc5d0 V8\uc758 \uae4a\uc740 \uc774\ud574\ub97c \uc6d0\ud558\uc2e0\ub2e4\uba74 \ubcf4\uae30\ub97c \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4. TurboShaft \uc804\uc5d0 \uba3c\uc800 \uc801\uc6a9\ub41c Meglev\uc5d0 \ub300\ud55c \uc18c\uc2dd\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6-901b-4f3e-8b9a-0e48601ad787#f54ee99d-a6f7-4c46-a206-7e843374f2f6\\">JIT\uac00 \ub354 \ube60\ub974\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4</a>\uc640 <a href=\\"https://medium.com/@yanguly/sparkplug-v8-baseline-javascript-compiler-758a7bc96e84\\">Sparkplug\uc5d0 \ub300\ud55c \uc124\uba85 \uae00</a>\uc744 \ucc38\uc870\ud574\uc8fc\uc138\uc694 \ud83d\ude0a</p><h2 data-notion-block-id=\\"1c5e548d-8a8e-80e9-a4d4-e5c4a749611c\\" id=\\"1c5e548d-8a8e-80e9-a4d4-e5c4a749611c\\">\ub370\uc774\ud130 undo\ub97c \uac04\ub2e8\ud558\uac8c \uad6c\ud604\ud558\uae30</h2><a href=\\"https://blog.julik.nl/2025/03/a-tiny-undo-stack\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.julik.nl/2025/03/a-tiny-undo-stack</a><p data-notion-block-id=\\"1c9e548d-8a8e-8030-942a-d5c3af13402b\\">undo/redo \uae30\ub2a5\uc744 \ub9cc\ub4dc\ub824\uba74 \ubcf4\ud1b5 \uc791\uc5c5\uc744 \ub098\uc5f4\ud574\ub193\uc740 array\uc758 index\ub97c \ud3ec\uc778\ud130\ub85c \uc0ac\uc6a9\ud558\ub294 \ud615\ud0dc\ub85c \uad6c\ud604\ud558\uac8c \ub429\ub2c8\ub2e4. \uc774 \ub54c index\uc758 \ud3ec\uc778\ud130\uac00 undefined\ub97c \ucc38\uc870\ud558\ub294 \uac83\uc744 \ubc29\uc9c0\ud558\uae30 \uc704\ud574 \ub450 \uac1c\uc758 array\ub97c \uc0ac\uc6a9\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \uad6c\ud604\ud558\ub294 \ubc29\ubc95\uc744 \uc81c\uc2dc\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1c7e548d-8a8e-801e-a630-ea9cc1b042ff\\" id=\\"1c7e548d-8a8e-801e-a630-ea9cc1b042ff\\">\uc624\ud508\uc18c\uc2a4\ub97c \ub9cc\ub4e4\uba74\uc11c \ubc30\uc6b4 \uc810\ub4e4</h2><a href=\\"https://www.youtube.com/watch?v=l3PxErcKeAI\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=l3PxErcKeAI</a><p data-notion-block-id=\\"1c9e548d-8a8e-8078-84b2-d0ef569b4b68\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/172e548d-8a8e-80af-ab22-de77c77b3e92#172e548d-8a8e-80af-8dbd-ee8123aab264\\">React Query, \uc815\ub9d0 \ub9cc\ub2a5\uc778\uac00?</a>\uc5d0 \uc774\uc5b4\uc11c \uc624\ud508\uc18c\uc2a4\ub97c \uac1c\ubc1c\ud558\uba74\uc11c \ubc30\uc6b4 \uc810\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \ubc1c\ud45c\uc601\uc0c1\uc785\ub2c8\ub2e4. <code>@tanstack/query</code>\uc758 \ucca0\ud559\uacfc \ub514\uc790\uc778\uc744 \uc9c0\ud0a4\uba74\uc11c \uc0ac\uc6a9\uc790\uc758 \uc694\uad6c\uc5d0 \ub300\uc751\ud558\ub294 \ubc95\uc5d0 \uc5b4\ub5bb\uac8c \uc0dd\uac01\ud558\ub294\uc9c0\uac00 \uc798 \ub2f4\uaca8\uc788\uc5b4 <code>@tanstack/query</code>\uc5d0 \uc9c0\uc2dd\uc774 \uae4a\uc9c0 \uc54a\uc544\ub3c4 \ubcf4\uae30 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1c3e548d-8a8e-80a6-9815-e96b1f1b8eb0\\" id=\\"1c3e548d-8a8e-80a6-9815-e96b1f1b8eb0\\">Polyfill\uc744 \uc5b8\uc81c \uc0ac\uc6a9\ud574\uc57c \ud560\uae4c</h2><a href=\\"https://web.dev/articles/baseline-and-polyfills\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://web.dev/articles/baseline-and-polyfills</a><p data-notion-block-id=\\"1c7e548d-8a8e-806b-bcb1-dffdb5c53928\\">\ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800 \ud658\uacbd\uc5d0\uc11c polyfill\uc740 \ubb34\uc5c7\uc774\uace0, \uc5b8\uc81c \uc801\uc6a9\ud574\uc57c \ud558\ub294\uc9c0, \uc5b4\ub5bb\uac8c \ub300\ud574\uc57c \ud560\uc9c0\uc5d0 \ub300\ud574 \uad00\uc810\uc744 \uc81c\uc2dc\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\ub4e4(\uc544\uc9c1\uae4c\uc9c0\ub294 PC\ub9cc..)\uc774 Baseline\uc744 \ucd9c\ubc94\ud558\uace0 \uacf5\ud1b5\ub418\ub294 \uad6c\ud604\uccb4\uac00 \ub9ce\uc544\uc9c0\uba74\uc11c polyfill\uc5d0 \ub300\ud55c \uad00\uc810 \ub610\ud55c baseline\uacfc RUM \ub370\uc774\ud130\ub85c \ub9de\ucdb0\uc11c \uc9c0\uc6d0\ud558\ub294 \uac83\uc774 \uc88b\uc544\ubcf4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1c7e548d-8a8e-80c3-bf63-ea5db4a4bf50\\" id=\\"1c7e548d-8a8e-80c3-bf63-ea5db4a4bf50\\">Vue\uc758 \ud604\uc7ac</h2><a href=\\"https://www.monterail.com/stateofvue\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.monterail.com/stateofvue</a><p data-notion-block-id=\\"1c9e548d-8a8e-800c-84c8-d7b151cdc0c5\\">Vue.js\ud300\uc774 \uc5b4\ub290 \uae30\ub2a5\uc5d0 \uc9d1\uc911\ud558\uace0 \uc788\uace0, \uac1c\ubc1c\uc790\ub4e4\uc740 \uc5b4\ub5a4 \uc7a5\ub2e8\uc810\uc744 \ub290\uaf08\uace0, \uc2e4\uc81c \uc801\uc6a9\uc0ac\ub840\ub294 \uc5b4\ub5a0\ud55c\uc9c0 \ubcf4\uc5ec\uc8fc\ub294 Vue.js \ub9ac\ud3ec\ud2b8\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1c3e548d-8a8e-80e1-ad08-eb7e974809d7\\" id=\\"1c3e548d-8a8e-80e1-ad08-eb7e974809d7\\">Firebase Dynamic Link \uc9c0\uc6d0 \uc911\uc9c0</h2><a href=\\"https://medium.com/@louis.lagrange/migrating-from-firebase-dynamic-links-a-practical-guide-9905bbb8f04d\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://medium.com/@louis.lagrange/migrating-from-firebase-dynamic-links-a-practical-guide-9905bbb8f04d</a><p data-notion-block-id=\\"1c9e548d-8a8e-804c-ad4f-f66e15087eee\\">Firebase Dynamic Link\uac00 \uc9c0\uc6d0 \uc911\ub2e8 \uacf5\uc9c0\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 Firebase\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 \uc5ec\ub7ec \uae30\ub2a5(\ud2b9\ud788 \uc9c0\uc5f0\ub41c \ub525\ub9c1\ud06c, deffered deep link)\uac00 \ud544\uc694 \uc5c6\ub2e4\uba74 \ubc31\uc5d4\ub4dc\uc5d0\uc11c \ub525\ub9c1\ud06c\ub97c \uc81c\uacf5\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c RN\uc5d0\uc11c\uc758 Firebase Dynamic Link\ub97c \ub300\uccb4\ud560 \uc218 \uc788\ub2e4\uace0 \uc54c\ub824\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1c3e548d-8a8e-8062-bcd7-e9588aa5a092\\" id=\\"1c3e548d-8a8e-8062-bcd7-e9588aa5a092\\">border-image\ub85c background-image \ub300\uccb4\ud558\uae30</h2><a href=\\"https://css-tricks.com/revisiting-css-border-image/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://css-tricks.com/revisiting-css-border-image/</a><p data-notion-block-id=\\"1c9e548d-8a8e-801a-8e98-c2d96a1f1351\\"><code>border-image</code>\ub97c \uc0ac\uc6a9\ud574\uc11c height\uac00 \uace0\uc815\ub418\uc9c0 \uc54a\uc740 \ub0b4\uc6a9\uc744 \uc774\ubbf8\uc9c0\uc640 \ud568\uaed8 \ub300\uc751\ud560 \uc218 \uc788\ub3c4\ub85d \uc548\ub0b4\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1c7e548d-8a8e-80aa-8b40-f83d1daee045\\" id=\\"1c7e548d-8a8e-80aa-8b40-f83d1daee045\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://tanstack.com/blog/announcing-tanstack-form-v1\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/blog/announcing-tanstack-form-v1</a><p data-notion-block-id=\\"1c7e548d-8a8e-80cd-a009-fc70e2a59baa\\">\uc5ec\ub7ec\uac00\uc9c0 \ud504\ub808\uc784\uc6cc\ud06c\uc5d0\uc11c \ud3fc\uc744 \ub2e4\ub8e8\ub294 \uc720\ud2f8\ub9ac\ud2f0\ub97c \uc81c\uacf5\ud558\ub294 <code>@tanstack/form</code>\uc758 \ubc84\uc804 1\uc774 \uacf5\uac1c\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://lynxjs.org/blog/lynx-open-source-roadmap-2025.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://lynxjs.org/blog/lynx-open-source-roadmap-2025.html</a><p data-notion-block-id=\\"1c7e548d-8a8e-80e5-80ba-ccb546c0ef06\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 Lynx\uac00 \uc5b4\ub5a4 \uacf3\uc5d0 \uc9d1\uc911\ud560 \uac83\uc778\uc9c0 \uc801\uc5b4\ub193\uc740 \ub85c\ub4dc\ub9f5\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/typedgrammar/typed-japanese/blob/main/blog.md\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/typedgrammar/typed-japanese/blob/main/blog.md</a><p data-notion-block-id=\\"1c9e548d-8a8e-80d7-8ae7-d79d34bad273\\">\ud0c0\uc785\uc2a4\ud06c\ub9bd\ud2b8\uc758 \ud0c0\uc785 \uc2dc\uc2a4\ud15c\uc744 \ud65c\uc6a9\ud574\uc11c \uc77c\ubcf8\uc5b4\ub97c \ud45c\ud604\ud558\ub294 \uc2dc\ub3c4\ub97c \ud574\ubcf8 \uc7ac\ubc0c\ub294 \ub808\ud3ec\uc9c0\ud1a0\ub9ac\uc785\ub2c8\ub2e4.</p><a href=\\"https://trpc.io/blog/announcing-trpc-v11\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://trpc.io/blog/announcing-trpc-v11</a><p data-notion-block-id=\\"1c9e548d-8a8e-8057-8806-f68e5fd31cf5\\">RSC \uc9c0\uc6d0, Tanstack Query \uc9c0\uc6d0\uc774 \ub208\uc5d0 \ub744\ub294 tRPC \ub9b4\ub9ac\uc988 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://developer.chrome.com/blog/carousels-with-css\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/blog/carousels-with-css</a><p data-notion-block-id=\\"1c9e548d-8a8e-804f-bc1a-ce7eb01273c8\\">\ucd5c\uc2e0 \ud06c\ub86c\uc5d0\uc11c CSS \uae30\ub2a5\uc744 \ud1b5\ud574 Carousel\uc744 \ub9cc\ub4e4 \uc218 \uc788\ub2e4\uace0 \ud558\ub294 \ud765\ubbf8\ub85c\uc6b4 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://developer.chrome.com/blog/a-customizable-select?hl=en\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/blog/a-customizable-select?hl=en</a><p data-notion-block-id=\\"1c9e548d-8a8e-80e1-bc5b-fcffb2d3be5b\\">\ucd5c\uc2e0 \ud06c\ub86c\uc5d0\uc11c <code>&#x3C;select></code>\uc694\uc18c\uc758 \uc5ec\ub7ec \ubd80\ubd84\uc744 \uc218\uc815\ud560 \uc218 \uc788\ub2e4\uace0 \ud569\ub2c8\ub2e4.</p>"}')}}]);